INSERT INTO learner_points (id, user_id, total_points, current_badge)
VALUES ('e26aba4c-0cf5-5851-b416-b06cc7786dd1', 'c5508410-d853-58d6-807b-736ed22fe2c6', 20, 'Newbie')
