INSERT INTO learner_points (id, user_id, total_points, current_badge)
VALUES ('a065e1a5-0ad8-51b4-9638-38630fc18413', '9f682dcb-1ad6-5530-8380-8dfda4c08e6f', 20, 'Newbie')
