INSERT INTO learner_points (id, user_id, total_points, current_badge)
VALUES ('d170695b-b7fa-537c-9de0-f6f0af6ea2ad', '4f06f73e-4bd5-52fd-9df9-b752013ab27a', 20, 'Newbie')
