    WHEN learner_points.total_points + EXCLUDED.total_points >= 41 THEN 'Achiever'::badge_level
    WHEN learner_points.total_points + EXCLUDED.total_points >= 21 THEN 'Explorer'::badge_level
    ELSE 'Newbie'::badge_level
  END,
  updated_at = NOW();

